import{_ as i,o as t,c as e,ah as a}from"./chunks/framework.DjU4PSOm.js";const q=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":3,"title":"인간이 병목이다","slug":"인간이-병목이다","link":"#인간이-병목이다","children":[]},{"level":2,"title":"프로젝트: 비움 스테이션","slug":"프로젝트-비움-스테이션","link":"#프로젝트-비움-스테이션","children":[{"level":3,"title":"프로젝트 개요","slug":"프로젝트-개요","link":"#프로젝트-개요","children":[]},{"level":3,"title":"문제 정의","slug":"문제-정의","link":"#문제-정의","children":[]},{"level":3,"title":"기존 서비스 리서치 결과 — 왜 빈틈인가","slug":"기존-서비스-리서치-결과-—-왜-빈틈인가","link":"#기존-서비스-리서치-결과-—-왜-빈틈인가","children":[]},{"level":3,"title":"시장 규모 조사","slug":"시장-규모-조사","link":"#시장-규모-조사","children":[]},{"level":3,"title":"하드웨어 설계 최종안 (계획서용, 실제 구현 X)","slug":"하드웨어-설계-최종안-계획서용-실제-구현-x","link":"#하드웨어-설계-최종안-계획서용-실제-구현-x","children":[]},{"level":3,"title":"BM","slug":"bm","link":"#bm","children":[]},{"level":3,"title":"이미 만든 것","slug":"이미-만든-것","link":"#이미-만든-것","children":[]},{"level":3,"title":"베타 신청 랜딩페이지 — 오늘 제작","slug":"베타-신청-랜딩페이지-—-오늘-제작","link":"#베타-신청-랜딩페이지-—-오늘-제작","children":[]},{"level":3,"title":"다음 단계 — 클로드 디자인으로 완성하기","slug":"다음-단계-—-클로드-디자인으로-완성하기","link":"#다음-단계-—-클로드-디자인으로-완성하기","children":[]}]}],"relativePath":"External-Activities/260827 바이브 코딩 창업캠프.md","filePath":"External-Activities/260827 바이브 코딩 창업캠프.md"}'),r={name:"External-Activities/260827 바이브 코딩 창업캠프.md"};function o(n,l,u,h,s,d){return t(),e("div",null,[...l[0]||(l[0]=[a('<p>글플 201호</p><ol><li>어디까지 쓰고 있는가?<br> 폴센트는 AI를 어떻게 쓰는가</li><li>실습<br> 만들기, 내보내기<br> 데모 만들고 -&gt; 광고 태우기</li></ol><p>주요 지표및 하위지표 설정후 추적<br> ex) 유저가 아낀돈 ,,,</p><p>단계별로 유저가 어디서 멈추는가를 확인 및 수정<br> 담기, 지켜보기, 알리기, 돌아오기의 사이클 확인</p><h3 id="인간이-병목이다" tabindex="-1"><strong>인간이 병목이다</strong> <a class="header-anchor" href="#인간이-병목이다" aria-label="Permalink to &quot;**인간이 병목이다**&quot;">​</a></h3><p>MCP로 옵시디언 연결해서 쓰죠?</p><p>못했을떄 어떻게 처리를 하는가에 최근 중점을 두고 있음..</p><hr><h2 id="프로젝트-비움-스테이션" tabindex="-1">프로젝트: 비움 스테이션 <a class="header-anchor" href="#프로젝트-비움-스테이션" aria-label="Permalink to &quot;프로젝트: 비움 스테이션&quot;">​</a></h2><h3 id="프로젝트-개요" tabindex="-1">프로젝트 개요 <a class="header-anchor" href="#프로젝트-개요" aria-label="Permalink to &quot;프로젝트 개요&quot;">​</a></h3><p>경북대학교 창업동아리 아이템 &quot;비움 스테이션&quot; — 캠퍼스 건물 내 음식물쓰레기+배달용기 처리 기기 및 운영 서비스.</p><h3 id="문제-정의" tabindex="-1">문제 정의 <a class="header-anchor" href="#문제-정의" aria-label="Permalink to &quot;문제 정의&quot;">​</a></h3><ul><li>캠퍼스 건물(라운지, 동아리방, 강의동)에는 음식물쓰레기통이 없음. 대학본부가 &quot;건물 내 음식 반입 금지 권고&quot;로 대응하며 정식 인프라 자체를 설치하지 않는 회피형 정책 운영 중.</li><li>실제 발생 문제: 음식물쓰레기를 변기/일반쓰레기에 혼합배출 → 수거업체 수거거부 사례, 환경미화원의 재분류 노동 부담, 라운지 냄새/위생 민원 반복.</li><li>경북대신문 보도: 2021년 대구시 무단투기 단속의 35.7%가 대학가 원룸촌에서 발생, 그중 약 26%가 경북대 인근(산격·대현·복현동).</li><li>기존 학교 대응(경고/계도, 수거함 확대)은 1~2개월만 효과 있고 재발 반복 — &quot;일회성 계도&quot;의 한계.</li></ul><h3 id="기존-서비스-리서치-결과-—-왜-빈틈인가" tabindex="-1">기존 서비스 리서치 결과 — 왜 빈틈인가 <a class="header-anchor" href="#기존-서비스-리서치-결과-—-왜-빈틈인가" aria-label="Permalink to &quot;기존 서비스 리서치 결과 — 왜 빈틈인가&quot;">​</a></h3><ul><li>오늘수거·커버링: 가정 문 앞 배달쓰레기 수거 대행. 서울/수도권 중심, 캠퍼스 건물 내부 발생원은 다루지 않음.</li><li>리코 &#39;업박스&#39;: 학내 &quot;식당&quot; 단위 대량 발생원 전용 B2B 서비스. 라운지·동아리방 등 소규모 개인 배출 지점은 대상 아님.</li><li>리턴잇/라라워시/더그리트 등 다회용기 서비스: 전부 &quot;수거 후 별도 공장에서 세척&quot; 모델. 현장 즉시 세척 기기는 업계가 이미 포기한 방식(상업용 식기세척기는 느리고 시끄러워 고객 접점 부적합).</li><li>LG 마이컵(텀블러 세척기): 개인 텀블러 재사용 세척용, 배관 있는 곳(카페/화장실 인근)에만 설치 가능한 배관 직결 방식. 목적이 다름(재사용 세척 vs 우리는 재활용 등급 전처리).</li><li>결론: &quot;캠퍼스 건물 내 소규모 배달쓰레기 발생 지점&quot;은 사각지대. 경쟁 대체가 아니라 원래 아무 인프라도 없던 곳을 처음 채우는 포지셔닝.</li></ul><h3 id="시장-규모-조사" tabindex="-1">시장 규모 조사 <a class="header-anchor" href="#시장-규모-조사" aria-label="Permalink to &quot;시장 규모 조사&quot;">​</a></h3><ul><li>전국 대학생 수(2025, 교육부·KEDI): 일반대 1,837,620명 + 전문대 494,057명, 대학원 포함 총 301만 6,724명.</li><li>대구경북: 대구경북경제자유구역청 자료 &quot;수도권 이남 최대 대학 집적지역, 매년 약 6.7만 명 졸업자 배출&quot;(2025.12.31 기준). 대구 주요 4개 대학(경북대·계명대·영남대·대구가톨릭대) 단순 합산 약 12만~13만 명, 전문대 포함 시 대구경북권 전체 약 20만 명 안팎 추정(정확한 공식 통계는 KESS 확인 필요).</li><li>경북대(2025.4 기준): 재학생 36,277명(학부 29,488, 대학원 6,789), 단과대 15개 내외.</li></ul><h3 id="하드웨어-설계-최종안-계획서용-실제-구현-x" tabindex="-1">하드웨어 설계 최종안 (계획서용, 실제 구현 X) <a class="header-anchor" href="#하드웨어-설계-최종안-계획서용-실제-구현-x" aria-label="Permalink to &quot;하드웨어 설계 최종안 (계획서용, 실제 구현 X)&quot;">​</a></h3><p>기기명(가칭): 비움 스테이션. 2단 분리형 스탠드(60×50×110cm), 학생회관/단과대 라운지 배치.<br> 설계 목표: 완전 자동 최종처리가 아니라 미화원·재활용업체가 다루기 쉬운 상태로 만드는 &quot;전처리기&quot;.</p><ul><li><strong>음식물칸</strong>: 열풍 건조(60~80℃)+교반으로 수분 90%↑ 제거, 부피 최대 80% 감량. 활성탄 필터+촉매산화 탈취. 밀폐 서랍형 저장, 적재 센서로 관리자 알림. 내부 스테인리스 304. 수거 주기 주 1~2회.</li><li><strong>용기칸(전처리 세척)</strong>: 1회용 용기 전제이므로 재사용 세척 기준 불필요, 목적은 &quot;재활용 선별장이 받아주는 등급&quot;으로만 만드는 것. 소량 배치(하루 5~8L) 순환 세척, 차아염소산나트륨(락스) 희석액 사용(1회용이라 식품안전 이슈 없음, 오히려 기름때 제거력 우수). 무한 재사용 아님, 배치 소진 후 폐수는 소형 배수통에 저장.</li><li><strong>설치 위치별 이원 전략</strong>: ①배관 있는 곳(화장실/탕비실 인근)은 마이컵처럼 배관 직결로 단순화(탱크 불필요, 세척수는 일반 잡배수 수준이라 별도 정화 불요) ②배관 없는 순수 라운지/동아리방은 소량 배치 탱크 방식 유지.</li><li><strong>공통 제어</strong>: QR 인증+터치 디스플레이(학생 앱 연동, 포인트 적립 트리거), 초음파/정전용량 센서, Wi-Fi/LTE 통신, 안전장치(손끼임 방지, 과열 방지, 정전 자동잠금).</li><li><strong>개발 단계</strong>: 1차 프로토타입(1개월, 기성 처리기 개조), 2차 프로토타입(2~3개월, 자체 하우징+센서+교내 시범설치 1대), 시제품 파일럿(4~6개월, 2~3대 확대).</li><li><strong>예상비용</strong>: 1차 약 200만원, 2차 500만~800만원, 양산 시 대당 약 300만원 목표.</li></ul><h3 id="bm" tabindex="-1">BM <a class="header-anchor" href="#bm" aria-label="Permalink to &quot;BM&quot;">​</a></h3><p>학교/학생회 대상 관리 대행 구독 서비스(설치비 대신 월/학기 운영관리비). 학교는 냄새·재발 관리 부담을 서비스에 위임. 배출 인증+포인트+학과 랭킹으로 &quot;설치해도 곧 재발하는&quot; 기존 실패 패턴(일회성 계도)을 방지하는 지속적 관리 구조가 핵심 차별점.</p><h3 id="이미-만든-것" tabindex="-1">이미 만든 것 <a class="header-anchor" href="#이미-만든-것" aria-label="Permalink to &quot;이미 만든 것&quot;">​</a></h3><p>소프트웨어 MVP 데모(HTML, <code>/mnt/user-data/outputs/bium-mvp.html</code>): 학생용 QR 인증 화면(음식물칸/용기칸 체크→포인트 적립→학과 랭킹보드) + 관리자 대시보드(건물별 기기 현황, 인증률/적재율 게이지, 재발 경고, 알림 로그).</p><h3 id="베타-신청-랜딩페이지-—-오늘-제작" tabindex="-1">베타 신청 랜딩페이지 — 오늘 제작 <a class="header-anchor" href="#베타-신청-랜딩페이지-—-오늘-제작" aria-label="Permalink to &quot;베타 신청 랜딩페이지 — 오늘 제작&quot;">​</a></h3><p>바이브 코딩 창업캠프 제출용으로, 실제 시장(재학생)에게 &quot;베타 신청하면 먼저 쓰게 해줄게&quot;라고 보여줄 랜딩페이지 제작. 문제정의(무단투기 통계) → 시장 빈틈(경쟁 서비스 비교표) → 하드웨어 작동 방식 → 운영 모델 → 베타 신청 폼 순서로 구성. 신청 폼은 오늘은 UI 데모용(실제 저장 없음).</p><h3 id="다음-단계-—-클로드-디자인으로-완성하기" tabindex="-1">다음 단계 — 클로드 디자인으로 완성하기 <a class="header-anchor" href="#다음-단계-—-클로드-디자인으로-완성하기" aria-label="Permalink to &quot;다음 단계 — 클로드 디자인으로 완성하기&quot;">​</a></h3><ol><li>오늘 캠프에는 지금 만든 Artifact 링크 그대로 제출.</li><li>Claude Design에서 이 HTML을 캔버스 초안(아트보드)으로 불러와 클릭-선택/속성 패널/인라인 텍스트 편집으로 세부 조정.</li><li>색·타이포·간격을 실제 브랜드 톤(로고, 팀 사진, 학교 로고 사용 승인 등)에 맞춰 손으로 다듬기.</li><li>베타 신청자 수, 실제 프로토타입 사진, 설치 확정 건물명 등 실제 진행 상황이 생기는 대로 콘텐츠 교체.</li><li>UI만 있는 신청 폼을 실제 저장 가능한 폼(런타임 capability 또는 구글폼 연동 등)으로 전환해 신청자 정보 실제 수집 시작.</li><li>Artifact 공유 메뉴로 학교 커뮤니티(에브리타임 등)에 링크 배포, 반응 보고 반복 개선.</li></ol>',28)])])}const b=i(r,[["render",o]]);export{q as __pageData,b as default};
